 "content": "def transform(grid):
    # Keep the two large solid-color objects, removing their noise markers;
    # background clutter and distractor objects are erased.
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    # At test/demonstration scale, intended colored rectangles are solid blocks
    # with occasional 6 marker interruptions. Identify their base colors as
    # the non-background colors occupying the largest connected components.
    from collections import deque, Counter
    counts = Counter(v for row in grid for v in row if v != 0)
    colors = [c for c, n in counts.most_common() if n >= 8]
    comps = []
    for c in colors:
        seen = set()
        for r in range(h):
            for x in range(w):
                if grid[r][x] != c or (r, x) in seen:
                    continue
                q = deque([(r, x)]); seen.add((r, x)); cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        p=(a+da,b+db)
                        if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==c:
                            seen.add(p); q.append(p)
                if len(cells) >= 8:
                    comps.append((len(cells), c, cells))
    # Retain contiguous major blocks, replacing marker holes inside their bounds.
    bycolor = {}
    for size,c,cells in sorted(comps, reverse=True):
        if c not in bycolor: bycolor[c] = (size,cells)
    chosen = sorted(bycolor.values(), reverse=True)[:2]
    for size,c,cells in chosen:
        rs=[r for r,x in cells]; xs=[x for r,x in cells]
        r0,r1,x0,x1=min(rs),max(rs),min(xs),max(xs)
        for r in range(r0,r1+1):
            for x in range(x0,x1+1):
                if grid[r][x] in (c,6): out[r][x]=c
    return out

if __name__ == '__main__':
    pass
",
