def transform(grid):
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    seen = set()
    # Keep coherent sizeable color patches; replace their bounding-box holes,
    # which are the sparse marker/noise cells interrupting the objects.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)]); seen.add((r, c)); cells=[]
            while q:
                a, b = q.popleft(); cells.append((a, b))
                for da, db in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(a+da,b+db)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
