 "content": "def transform(grid):
    """Restore near-solid rectangular patches and remove isolated noise."""
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    components = []

    # 4-neighbor components distinguish adjacent patches separated by gaps.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            queue = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while queue:
                y, x = queue.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        queue.append((yy, xx))
            components.append((color, cells))

    # First restore each coherent, near-rectangular patch. Doing this before
    # noise removal also repairs singleton intrusions embedded in target patches.
    restored = set()
    for color, cells in components:
        if len(cells) < 4:
            continue
        r0 = min(y for y, _ in cells)
        r1 = max(y for y, _ in cells)
        c0 = min(x for _, x in cells)
        c1 = max(x for _, x in cells)
        area = (r1 - r0 + 1) * (c1 - c0 + 1)
        if len(cells) / area >= 0.80:
            for y in range(r0, r1 + 1):
                for x in range(c0, c1 + 1):
                    out[y][x] = color
                    restored.add((y, x))

    # Isolated non-background pixels outside restored patches are speckles.
    for _, cells in components:
        if len(cells) == 1:
            y, x = cells[0]
            if (y, x) not in restored:
                out[y][x] = background

    # Some demos include two isolated markers inside a nearly rectangular patch;
    # identify such sparse interruptions as part of the local block. A target
    # patch can be recognized by same-color support on both sides of the mark.
    # (The bounding-box restoration above handles the dense cases.)
    for r in range(h):
        for c in range(w):
            if out[r][c] == background and grid[r][c] != background:
                continue
    return out


